if (!defined('ABSPATH')) exit;

function gd_client_portal_billing_invoices_table(){ global $wpdb; return $wpdb->prefix.'gd_portal_invoices'; }
function gd_client_portal_billing_quotes_table(){ global $wpdb; return $wpdb->prefix.'gd_portal_quotes'; }

function gd_client_portal_billing_activate_tables(){
    global $wpdb; require_once ABSPATH.'wp-admin/includes/upgrade.php'; $c=$wpdb->get_charset_collate();
    $i=gd_client_portal_billing_invoices_table(); $q=gd_client_portal_billing_quotes_table();
    dbDelta("CREATE TABLE $i (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,invoice_number varchar(50) NOT NULL,tenant_id bigint(20) unsigned NOT NULL DEFAULT 0,user_id bigint(20) unsigned NOT NULL DEFAULT 0,project_id bigint(20) unsigned NOT NULL DEFAULT 0,order_id bigint(20) unsigned NOT NULL DEFAULT 0,quote_id bigint(20) unsigned NOT NULL DEFAULT 0,currency varchar(10) NOT NULL DEFAULT 'GHS',subtotal decimal(20,2) NOT NULL DEFAULT 0.00,tax decimal(20,2) NOT NULL DEFAULT 0.00,total decimal(20,2) NOT NULL DEFAULT 0.00,amount_paid decimal(20,2) NOT NULL DEFAULT 0.00,due_date date NULL,status varchar(30) NOT NULL DEFAULT 'unpaid',payment_reference varchar(100) NULL,description text NULL,created_at datetime DEFAULT CURRENT_TIMESTAMP,updated_at datetime DEFAULT CURRENT_TIMESTAMP,paid_at datetime NULL,PRIMARY KEY(id),UNIQUE KEY invoice_number(invoice_number),KEY tenant_id(tenant_id),KEY user_id(user_id),KEY project_id(project_id),KEY order_id(order_id),KEY status(status)) $c;");
    dbDelta("CREATE TABLE $q (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,quote_number varchar(50) NOT NULL,tenant_id bigint(20) unsigned NOT NULL DEFAULT 0,user_id bigint(20) unsigned NOT NULL DEFAULT 0,project_id bigint(20) unsigned NOT NULL DEFAULT 0,title varchar(255) NOT NULL,description longtext NULL,currency varchar(10) NOT NULL DEFAULT 'GHS',amount decimal(20,2) NOT NULL DEFAULT 0.00,status varchar(30) NOT NULL DEFAULT 'draft',valid_until date NULL,created_by bigint(20) unsigned NOT NULL DEFAULT 0,created_at datetime DEFAULT CURRENT_TIMESTAMP,updated_at datetime DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY quote_number(quote_number),KEY tenant_id(tenant_id),KEY user_id(user_id),KEY project_id(project_id),KEY status(status)) $c;");
}
function gd_client_portal_billing_upgrade(){ if(absint(get_option('gd_client_portal_billing_schema_version',0))<1){ gd_client_portal_billing_activate_tables(); update_option('gd_client_portal_billing_schema_version',1); } }
// Schema lifecycle is managed centrally by GDCP_Migration_Manager (v6.8+).

function gd_client_portal_billing_money($amount,$currency='GHS'){ return esc_html(number_format((float)$amount,2).' '.strtoupper($currency)); }
function gd_client_portal_billing_statuses(){ return array('draft'=>'Draft','unpaid'=>'Unpaid','part_paid'=>'Part paid','paid'=>'Paid','overdue'=>'Overdue','cancelled'=>'Cancelled'); }
function gd_client_portal_billing_display_status($row){ if(!$row)return ''; $status=$row->status; if(in_array($status,array('unpaid','part_paid'),true) && !empty($row->due_date) && strtotime($row->due_date.' 23:59:59')<current_time('timestamp')) $status='overdue'; return $status; }
function gd_client_portal_billing_quote_statuses(){ return array('draft'=>'Draft','sent'=>'Sent','accepted'=>'Accepted','declined'=>'Declined','expired'=>'Expired'); }
function gd_client_portal_billing_invoice_access($row){
    if(!$row || !gd_client_portal_verify_request()) return false;
    if(gd_client_portal_is_platform_admin()) return true;
    $tenant=absint(gd_client_portal_get_current_tenant_id()); if($tenant<=0 || absint($row->tenant_id)!==$tenant) return false;
    return gd_client_portal_user_is_tenant_admin() || absint($row->user_id)===gd_client_portal_cached_current_user_id();
}
function gd_client_portal_billing_quote_access($row,$admin=false){
    if(!$row || !gd_client_portal_verify_request()) return false;
    if(gd_client_portal_is_platform_admin()) return true;
    $tenant=absint(gd_client_portal_get_current_tenant_id()); if($tenant<=0 || absint($row->tenant_id)!==$tenant) return false;
    return $admin ? gd_client_portal_user_is_tenant_admin() : (gd_client_portal_user_is_tenant_admin() || absint($row->user_id)===gd_client_portal_cached_current_user_id());
}
function gd_client_portal_billing_get_invoices($limit=100){
    global $wpdb; $t=gd_client_portal_billing_invoices_table(); if(!gd_client_portal_verify_request()) return array();
    $where=array('1=1');$p=array();
    if(!gd_client_portal_is_platform_admin()){ $tenant=absint(gd_client_portal_get_current_tenant_id()); if($tenant<=0)return array();$where[]='tenant_id=%d';$p[]=$tenant;if(!gd_client_portal_user_is_tenant_admin()){$where[]='user_id=%d';$p[]=gd_client_portal_cached_current_user_id();} }
    $sql="SELECT * FROM $t WHERE ".implode(' AND ',$where).' ORDER BY id DESC LIMIT '.max(1,min(200,absint($limit)));
    return $p?$wpdb->get_results($wpdb->prepare($sql,$p)):$wpdb->get_results($sql);
}
function gd_client_portal_billing_get_quotes($limit=100){
    global $wpdb; $t=gd_client_portal_billing_quotes_table(); if(!gd_client_portal_verify_request()) return array();
    $where=array('1=1');$p=array();
    if(!gd_client_portal_is_platform_admin()){ $tenant=absint(gd_client_portal_get_current_tenant_id()); if($tenant<=0)return array();$where[]='tenant_id=%d';$p[]=$tenant;if(!gd_client_portal_user_is_tenant_admin()){$where[]='user_id=%d';$p[]=gd_client_portal_cached_current_user_id();} }
    $sql="SELECT * FROM $t WHERE ".implode(' AND ',$where).' ORDER BY id DESC LIMIT '.max(1,min(200,absint($limit)));
    return $p?$wpdb->get_results($wpdb->prepare($sql,$p)):$wpdb->get_results($sql);
}
function gd_client_portal_billing_invoice_by_order($order_id){global $wpdb;return $wpdb->get_row($wpdb->prepare('SELECT * FROM '.gd_client_portal_billing_invoices_table().' WHERE order_id=%d LIMIT 1',absint($order_id)));}
function gd_client_portal_billing_invoice_number(){ return 'GD-INV-'.gmdate('Y').'-'.str_pad((string)wp_rand(1,999999),6,'0',STR_PAD_LEFT); }
function gd_client_portal_billing_quote_number(){ return 'GD-QT-'.gmdate('Y').'-'.str_pad((string)wp_rand(1,999999),6,'0',STR_PAD_LEFT); }

function gd_client_portal_billing_sync_order($order_id){ return gdcp_billing_service()->sync_woocommerce_order($order_id); }
function gd_client_portal_billing_order_hook($order_id){gd_client_portal_billing_sync_order($order_id);}
add_action('woocommerce_payment_complete','gd_client_portal_billing_order_hook',30);add_action('woocommerce_order_status_processing','gd_client_portal_billing_order_hook',30);add_action('woocommerce_order_status_completed','gd_client_portal_billing_order_hook',30);add_action('woocommerce_order_status_on-hold','gd_client_portal_billing_order_hook',30);

function gd_client_portal_billing_admin_create_quote(){
    if(!is_user_logged_in() || !gd_client_portal_verify_request() || !(gd_client_portal_is_platform_admin()||gd_client_portal_user_is_tenant_admin())) wp_send_json_error(array('message'=>'Access denied.'),403);
    check_ajax_referer('gd_client_portal_billing_admin','nonce');
    $tenant=absint($_POST['tenant_id']??0); if(!gd_client_portal_is_platform_admin())$tenant=absint(gd_client_portal_get_current_tenant_id());
    $user=absint($_POST['user_id']??0); $project=absint($_POST['project_id']??0);
    if($tenant<=0||!$user||!gd_client_portal_is_platform_admin() && function_exists('gd_client_portal_get_user_tenant_id') && absint(gd_client_portal_get_user_tenant_id($user))!==$tenant) wp_send_json_error(array('message'=>'Invalid client or tenant.'),403);
    $result=gdcp_billing_service()->create_quote(array('tenant_id'=>$tenant,'user_id'=>$user,'project_id'=>$project,'title'=>$_POST['title']??'','description'=>$_POST['description']??'','currency'=>$_POST['currency']??'GHS','amount'=>(float)($_POST['amount']??0),'valid_until'=>$_POST['valid_until']??''));
    if(is_wp_error($result)) wp_send_json_error(array('message'=>$result->get_error_message()),$result->get_error_code()==='invalid_project'?403:400);
    $data=$result['record']; if(function_exists('gd_client_portal_create_notification'))gd_client_portal_create_notification($user,__('New service quote','gd-client-portal'),sprintf(__('A new quote %s is available for your review.','gd-client-portal'),$data->quote_number),'billing',$project,$tenant);
    if(function_exists('gd_client_portal_audit_log'))gd_client_portal_audit_log('quote_created',$data->title,$project,$tenant,$data->description,'quote',$data->id,array('amount'=>(float)$data->amount,'currency'=>$data->currency));
    wp_send_json_success(array('id'=>$data->id,'message'=>'Quote created and sent.'));
}
add_action('wp_ajax_gd_client_portal_billing_create_quote','gd_client_portal_billing_admin_create_quote');

function gd_client_portal_billing_quote_decision(){
    if(!is_user_logged_in()||!gd_client_portal_verify_request())wp_send_json_error(array('message'=>'Access denied.'),403); check_ajax_referer('gd_client_portal_billing','nonce');
    $id=absint($_POST['quote_id']??0); $status=sanitize_key($_POST['status']??''); $row=gdcp_billing_service()->get_quote_for_access($id); if(!$row||!gd_client_portal_billing_quote_access($row))wp_send_json_error(array('message'=>'Access denied.'),403);
    $result=gdcp_billing_service()->decide_quote($id,$status); if(is_wp_error($result))wp_send_json_error(array('message'=>$result->get_error_message()),400);
    if($status==='accepted')do_action('gd_client_portal_quote_accepted',$result); if(function_exists('gd_client_portal_create_notification')){foreach(get_users(array('role'=>'gd_client_portal_tenant_admin','meta_key'=>'gd_client_portal_tenant_id','meta_value'=>$result->tenant_id,'fields'=>'ID')) as $uid)gd_client_portal_create_notification($uid,__('Quote decision','gd-client-portal'),sprintf(__('%s was %s.','gd-client-portal'),$result->quote_number,$status),'billing',$result->project_id,$result->tenant_id);}
    wp_send_json_success(array('message'=>'Quote updated.'));
}
add_action('wp_ajax_gd_client_portal_billing_quote_decision','gd_client_portal_billing_quote_decision');

function gd_client_portal_render_billing_center(){
    if(!is_user_logged_in()||!gd_client_portal_verify_request())return '<div class="gd-billing-gate">Please log in to access your Financial Center.</div>';
    $invoices=gd_client_portal_billing_get_invoices();$quotes=gd_client_portal_billing_get_quotes();$unpaid=0;$paid=0;foreach($invoices as $i){$balance=max(0,(float)$i->total-(float)$i->amount_paid);if($balance>0&&gd_client_portal_billing_display_status($i)!=='cancelled')$unpaid+=$balance;$paid+=(float)$i->amount_paid;}
    wp_enqueue_style('gd-client-portal-billing',GD_CLIENT_PORTAL_URL.'assets/billing.css',array('gd-client-portal'),GD_CLIENT_PORTAL_VERSION);wp_enqueue_script('gd-client-portal-billing',GD_CLIENT_PORTAL_URL.'assets/billing.js',array(),GD_CLIENT_PORTAL_VERSION,true);wp_localize_script('gd-client-portal-billing','GDBilling',array('ajax_url'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('gd_client_portal_billing')));
    ob_start();?><div class="gd-billing-center"><section class="gd-billing-hero"><div><span>Financial workspace</span><h2>Billing &amp; Financial Center</h2><p>Review invoices, payment history, quotes and outstanding balances in one place.</p></div></section><div class="gd-billing-summary"><div><small>Outstanding</small><strong><?php echo gd_client_portal_billing_money($unpaid);?></strong></div><div><small>Paid</small><strong><?php echo gd_client_portal_billing_money($paid);?></strong></div><div><small>Invoices</small><strong><?php echo count($invoices);?></strong></div><div><small>Quotes</small><strong><?php echo count($quotes);?></strong></div></div><section class="gd-billing-panel"><div class="gd-billing-panel-head"><h3>Invoices &amp; payments</h3></div><?php if(!$invoices):?><div class="gd-billing-empty">No invoices have been issued yet.</div><?php else:?><div class="gd-billing-table-wrap"><table><thead><tr><th>Invoice</th><th>Project</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($invoices as $i):$balance=max(0,(float)$i->total-(float)$i->amount_paid);?><tr><td><strong><?php echo esc_html($i->invoice_number);?></strong><small><?php echo esc_html($i->description);?></small></td><td><?php echo $i->project_id?'#'.intval($i->project_id):'—';?></td><td><?php echo gd_client_portal_billing_money($i->total,$i->currency);?></td><td><?php echo gd_client_portal_billing_money($i->amount_paid,$i->currency);?></td><td><?php echo gd_client_portal_billing_money($balance,$i->currency);?></td><td><span class="gd-billing-status status-<?php echo esc_attr(gd_client_portal_billing_display_status($i));?>"><?php echo esc_html(gd_client_portal_billing_statuses()[gd_client_portal_billing_display_status($i)]??gd_client_portal_billing_display_status($i));?></span></td><td><?php echo esc_html(wp_date(get_option('date_format'),strtotime($i->created_at)));?><div class="gd-billing-actions"><a class="gd-billing-link" target="_blank" href="<?php echo esc_url(add_query_arg('gdcp_invoice_pdf',absint($i->id),home_url('/')));?>">Download PDF</a><?php if(function_exists('gd_client_portal_paystack_enabled') && gd_client_portal_paystack_enabled() && gd_client_portal_payment_balance($i)>0):?><button type="button" class="gd-pay-invoice" data-id="<?php echo intval($i->id);?>">Pay now</button><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="gd-billing-panel"><div class="gd-billing-panel-head"><h3>Payment history</h3></div><?php $payment_rows=array(); foreach($invoices as $inv){ if(function_exists('gd_client_portal_payment_get_for_invoice')) foreach((array)gd_client_portal_payment_get_for_invoice($inv->id) as $pr){$payment_rows[]=array('invoice'=>$inv,'payment'=>$pr);} } if(!$payment_rows):?><div class="gd-billing-empty">No payments recorded yet.</div><?php else:?><div class="gd-billing-table-wrap"><table><thead><tr><th>Reference</th><th>Invoice</th><th>Amount</th><th>Gateway</th><th>Channel</th><th>Date</th></tr></thead><tbody><?php foreach($payment_rows as $pr):?><tr><td><strong><?php echo esc_html($pr['payment']->reference);?></strong></td><td><?php echo esc_html($pr['invoice']->invoice_number);?></td><td><?php echo gd_client_portal_billing_money($pr['payment']->amount,$pr['payment']->currency);?></td><td><?php echo esc_html(ucfirst($pr['payment']->gateway));?></td><td><?php echo esc_html($pr['payment']->channel?:'—');?></td><td><?php echo esc_html(wp_date(get_option('date_format').' '.get_option('time_format'),strtotime($pr['payment']->created_at)));?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="gd-billing-panel"><div class="gd-billing-panel-head"><h3>Quotes</h3></div><?php if(!$quotes):?><div class="gd-billing-empty">No quotes available.</div><?php else: foreach($quotes as $q):?><article class="gd-quote-card"><div><strong><?php echo esc_html($q->quote_number);?></strong><h4><?php echo esc_html($q->title);?></h4><p><?php echo esc_html(wp_trim_words($q->description,30));?></p></div><div class="gd-quote-price"><?php echo gd_client_portal_billing_money($q->amount,$q->currency);?><span class="gd-billing-status status-<?php echo esc_attr($q->status);?>"><?php echo esc_html(gd_client_portal_billing_quote_statuses()[$q->status]??$q->status);?></span><?php if($q->status==='sent' && absint($q->user_id)===gd_client_portal_cached_current_user_id()):?><div><button class="gd-quote-decision" data-id="<?php echo intval($q->id);?>" data-status="accepted">Accept</button><button class="gd-quote-decision secondary" data-id="<?php echo intval($q->id);?>" data-status="declined">Decline</button></div><?php endif;?></div></article><?php endforeach;endif;?></section></div><?php return ob_get_clean();}
add_shortcode('gd_billing_center','gd_client_portal_render_billing_center');
add_shortcode('gd_financial_center','gd_client_portal_render_billing_center');

