function gd_client_portal_render_billing_admin(){
    if(!gd_client_portal_user_can_access_admin())wp_die(esc_html__('You do not have permission to access billing.','gd-client-portal'));
    $invoices=gd_client_portal_billing_get_invoices(200);$quotes=gd_client_portal_billing_get_quotes(200);$users=gd_client_portal_is_platform_admin()?get_users(array('number'=>200,'fields'=>array('ID','display_name','user_email'))):get_users(array('number'=>200,'meta_key'=>'gd_client_portal_tenant_id','meta_value'=>gd_client_portal_get_current_tenant_id(),'fields'=>array('ID','display_name','user_email')));
    ?><div class="wrap gd-billing-admin"><h1>Billing &amp; Financial Center</h1><p>Create service quotes and monitor portal invoices synced from WooCommerce.</p><hr><h2>Create Quote</h2><form id="gd-billing-quote-form"><input type="hidden" name="action" value="gd_client_portal_billing_create_quote"><input type="hidden" name="nonce" value="<?php echo esc_attr(wp_create_nonce('gd_client_portal_billing_admin'));?>"><?php if(gd_client_portal_is_platform_admin()):?><p><label>Tenant <select name="tenant_id" required><option value="">Select tenant</option><?php foreach((array)gd_client_portal_get_all_tenants() as $tid=>$tenant):?><option value="<?php echo intval($tid);?>"><?php echo esc_html($tenant['name']??('Tenant #'.intval($tid)));?></option><?php endforeach;?></select></label></p><?php else:?><input type="hidden" name="tenant_id" value="<?php echo intval(gd_client_portal_get_current_tenant_id());?>"><?php endif;?><table class="form-table"><tr><th>Client</th><td><select name="user_id" required><option value="">Select client</option><?php foreach($users as $u):?><option value="<?php echo intval($u->ID);?>"><?php echo esc_html($u->display_name.' — '.$u->user_email);?></option><?php endforeach;?></select></td></tr><tr><th>Title</th><td><input name="title" class="regular-text" required></td></tr><tr><th>Description</th><td><textarea name="description" class="large-text" rows="3"></textarea></td></tr><tr><th>Project ID</th><td><input type="number" name="project_id" min="0" value="0"></td></tr><tr><th>Amount</th><td><input type="number" name="amount" step="0.01" min="0" required> <input name="currency" value="GHS" size="5"></td></tr><tr><th>Valid until</th><td><input type="date" name="valid_until"></td></tr></table><p><button class="button button-primary" type="submit">Create &amp; Send Quote</button> <span id="gd-billing-quote-result"></span></p></form><hr><h2>Invoices</h2><table class="widefat striped"><thead><tr><th>Invoice</th><th>Client</th><th>Project</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php foreach($invoices as $i):$bal=max(0,(float)$i->total-(float)$i->amount_paid);$u=gd_client_portal_cached_user($i->user_id);?><tr><td><?php echo esc_html($i->invoice_number);?></td><td><?php echo esc_html($u?$u->display_name:'—');?></td><td><?php echo $i->project_id?'#'.intval($i->project_id):'—';?></td><td><?php echo gd_client_portal_billing_money($i->total,$i->currency);?></td><td><?php echo gd_client_portal_billing_money($i->amount_paid,$i->currency);?></td><td><?php echo gd_client_portal_billing_money($bal,$i->currency);?></td><td><?php echo esc_html(gd_client_portal_billing_statuses()[$i->status]??$i->status);?></td></tr><?php endforeach;?></tbody></table><hr><h2>Record Payment</h2><form id="gd-payment-manual-form"><input type="hidden" name="action" value="gd_client_portal_payment_manual"><input type="hidden" name="nonce" value="<?php echo esc_attr(wp_create_nonce('gd_client_portal_payment_admin'));?>"><p><select name="invoice_id" required><option value="">Select invoice</option><?php foreach($invoices as $i):?><option value="<?php echo intval($i->id);?>"><?php echo esc_html($i->invoice_number.' — '.gd_client_portal_billing_money(gd_client_portal_payment_balance($i),$i->currency));?></option><?php endforeach;?></select> <input name="amount" type="number" step="0.01" min="0.01" placeholder="Amount" required> <input name="reference" placeholder="Reference" required> <input name="channel" placeholder="Bank transfer / cash / other" value="Bank transfer"> <button class="button button-primary" type="submit">Record Payment</button> <span id="gd-payment-manual-result"></span></p></form><hr><h2>Quotes</h2><table class="widefat striped"><thead><tr><th>Quote</th><th>Client</th><th>Title</th><th>Amount</th><th>Status</th><th>Valid until</th></tr></thead><tbody><?php foreach($quotes as $q):$u=gd_client_portal_cached_user($q->user_id);?><tr><td><?php echo esc_html($q->quote_number);?></td><td><?php echo esc_html($u?$u->display_name:'—');?></td><td><?php echo esc_html($q->title);?></td><td><?php echo gd_client_portal_billing_money($q->amount,$q->currency);?></td><td><?php echo esc_html(gd_client_portal_billing_quote_statuses()[$q->status]??$q->status);?></td><td><?php echo esc_html($q->valid_until?:'—');?><?php if($q->status==='accepted'):?><button type="button" class="button gd-quote-invoice" data-id="<?php echo intval($q->id);?>">Convert to Invoice</button><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
    <?php
    wp_enqueue_style('gd-client-portal-billing-admin',GD_CLIENT_PORTAL_URL.'assets/billing.css',array(),GD_CLIENT_PORTAL_VERSION);wp_enqueue_script('gd-client-portal-billing-admin',GD_CLIENT_PORTAL_URL.'assets/billing.js',array(),GD_CLIENT_PORTAL_VERSION,true);wp_enqueue_script('gd-client-portal-payments-admin',GD_CLIENT_PORTAL_URL.'assets/payments.js',array('jquery'),GD_CLIENT_PORTAL_VERSION,true);wp_localize_script('gd-client-portal-billing-admin','GDBillingAdmin',array('ajax_url'=>admin_url('admin-ajax.php'),'billing_nonce'=>wp_create_nonce('gd_client_portal_billing_admin')));wp_localize_script('gd-client-portal-billing-admin','GDCPPayments',array('ajax_url'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('gd_client_portal_payment'),'admin_nonce'=>wp_create_nonce('gd_client_portal_payment_admin'),'billing_nonce'=>wp_create_nonce('gd_client_portal_billing_admin')));
}
